fn main() {
    // `generate_context!` needs the built webview assets from `npm run build`.
    //
    // The app manifest makes the app's OWN commands ACL-gated: each listed
    // command gets autogenerated `allow-<command>` / `deny-<command>`
    // permissions, and a window can invoke it only when a capability grants it
    // (see capabilities/default.json). Without this list, app commands are
    // reachable from every window regardless of capabilities.
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(
        tauri_build::AppManifest::new().commands(&["core_request_frame", "core_socket_status"]),
    ))
    .expect("failed to run tauri-build");
}
